import { Card, ConfigProvider, Layout, theme, Typography } from "antd";
import React, { useState } from "react";
import ChatComponent from "./components/ChatComponent";
import PdfUploader from "./components/PdfUploader";
import RenderQA from "./components/RenderQA";

const { Header, Content } = Layout;
const { Title, Text } = Typography;

const App = () => {
  const [conversation, setConversation] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleResp = (question, answer) => {
    setConversation((prev) => [...prev, { question, answer }]);
  };

  // --- 样式定义 (CSS-in-JS) ---

  // 1. 全局背景：使用极淡的蓝灰色渐变，比纯白更有质感
  const layoutStyle = {
    height: "100vh",
    background: "linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)",
    display: "flex",
    flexDirection: "column",
  };

  // 2. 顶部导航：纯白背景 + 底部阴影，突出层次
  const headerStyle = {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    backgroundColor: "rgba(255, 255, 255, 0.9)", // 轻微透明
    backdropFilter: "blur(10px)", // 毛玻璃
    borderBottom: "1px solid #eaeaea",
    padding: "0 40px",
    height: "64px",
    zIndex: 10,
  };

  // 3. 标题样式：渐变色文字，呼应 "Hemisphere" (半球/双脑) 的概念
  const titleStyle = {
    margin: 0,
    background: "linear-gradient(45deg, #1677FF, #52C41A)", // 蓝绿渐变
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    fontWeight: "bold",
    fontSize: "24px",
    cursor: "default",
  };

  // 4. 内容区域：限制最大宽度，居中，使用 Flex 让它占满中间空间
  const contentStyle = {
    flex: 1, // 关键：让内容区域自动撑开，占据 Header 和 Footer 之间的所有空间
    width: "100%",
    maxWidth: "1000px", // 限制在大屏幕上的太宽
    margin: "0 auto",
    padding: "20px",
    display: "flex",
    flexDirection: "column",
    overflow: "hidden", // 防止整个页面滚动
  };

  // 5. 聊天记录区域：允许独立滚动
  const scrollableAreaStyle = {
    flex: 1, // 占满剩余高度
    overflowY: "auto", // 只有这个区域滚动
    padding: "20px",
    paddingBottom: "100px", // 底部留白，防止内容被输入框遮挡
    scrollbarWidth: "thin", // 针对 Firefox 优化滚动条
  };

  // 6. 底部输入框容器：悬浮卡片 + 毛玻璃
  const footerStyle = {
    position: "fixed",
    bottom: "30px",
    left: "50%",
    transform: "translateX(-50%)",
    width: "90%",
    maxWidth: "800px",
    padding: "0",
    zIndex: 100,
  };

  return (
    // 使用 ConfigProvider 可以全局配置 Ant Design 的主题色
    <ConfigProvider
      theme={{
        algorithm: theme.defaultAlgorithm,
        token: {
          colorPrimary: "#1677FF",
          borderRadius: 12, // 全局圆角更圆润
        },
      }}
    >
      <Layout style={layoutStyle}>
        {/* === 顶部 === */}
        <Header style={headerStyle}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <span style={{ fontSize: "28px" }}>🧠</span>
            <Title level={3} style={titleStyle}>
              Hemisphere AI
            </Title>
          </div>
          <Text type="secondary" style={{ fontSize: "12px" }}>
            Dual-Brain RAG & MCP Architecture
          </Text>
        </Header>

        {/* === 中间内容 === */}
        <Content style={contentStyle}>
          {/* 上传区域：用 Card 包裹，增加投影，显得更精致 */}
          <div style={{ marginBottom: "20px" }}>
            <Card
              bordered={false}
              style={{
                boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
                background: "rgba(255,255,255,0.6)",
              }}
              bodyStyle={{ padding: "12px" }}
            >
              <PdfUploader />
            </Card>
          </div>

          {/* 聊天显示区域：Flex 布局自动撑开 */}
          <div style={scrollableAreaStyle} className="chat-container">
            <RenderQA conversation={conversation} isLoading={isLoading} />
          </div>
        </Content>

        {/* === 底部输入框 === */}
        <div style={footerStyle}>
          {/* 给输入框加一个很强的阴影，让它看起来是浮在上面的 */}
          <div
            style={{
              boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
              borderRadius: "12px",
              background: "#fff",
              overflow: "hidden",
            }}
          >
            <ChatComponent
              handleResp={handleResp}
              isLoading={isLoading}
              setIsLoading={setIsLoading}
            />
          </div>
        </div>
      </Layout>
    </ConfigProvider>
  );
};

export default App;
